(function () {
  'use strict';

  var STORAGE_KEY = 'todos-todomvc';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var editingId = null;
  var currentFilter = '/';

  // --- DOM references (set after DOM is ready) ---

  var newTodoInput, todoList, toggleAll, mainSection, footer, todoCount, clearCompletedBtn, filterLinks;

  function cacheDom() {
    newTodoInput = document.querySelector('.new-todo');
    todoList = document.querySelector('.todo-list');
    toggleAll = document.querySelector('#toggle-all');
    mainSection = document.querySelector('.main');
    footer = document.querySelector('.footer');
    todoCount = document.querySelector('.todo-count');
    clearCompletedBtn = document.querySelector('.clear-completed');
    filterLinks = document.querySelectorAll('.filters a');
  }

  // --- Persistence ---

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) { /* ignore */ }
  }

  function load() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      todos = data ? JSON.parse(data) : [];
    } catch (e) {
      todos = [];
    }
  }

  // --- ID generation ---

  var _idCounter = 1;
  function generateId() {
    return Date.now() + (_idCounter++);
  }

  // --- Rendering ---

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  function render() {
    if (!todoList) return;

    var filtered = todos.filter(function (todo) {
      if (currentFilter === '/active') return !todo.completed;
      if (currentFilter === '/completed') return todo.completed;
      return true;
    });

    // Build the list HTML
    var html = '';
    for (var i = 0; i < filtered.length; i++) {
      var todo = filtered[i];
      var completedClass = todo.completed ? ' completed' : '';
      var editingClass = editingId === todo.id ? ' editing' : '';
      var checkedAttr = todo.completed ? ' checked' : '';
      html += '<li data-id="' + todo.id + '" class="' + completedClass + editingClass + '">' +
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + checkedAttr + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">' +
      '</li>';
    }
    todoList.innerHTML = html;

    updateCount();
    updateToggleAll();
    updateClearCompleted();
    updateMainAndFooter();
    updateFilterLinks();
  }

  function updateCount() {
    if (!todoCount) return;
    var activeCount = 0;
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) activeCount++;
    }
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
      (activeCount === 1 ? 'item' : 'items') + ' left';
  }

  function updateToggleAll() {
    if (!toggleAll) return;
    var allCompleted = todos.length > 0;
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) { allCompleted = false; break; }
    }
    toggleAll.checked = allCompleted;
  }

  function updateClearCompleted() {
    if (!clearCompletedBtn) return;
    var hasCompleted = false;
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].completed) { hasCompleted = true; break; }
    }
    clearCompletedBtn.style.display = hasCompleted ? '' : 'none';
  }

  function updateMainAndFooter() {
    if (!mainSection || !footer) return;
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footer.style.display = '';
    }
  }

  function updateFilterLinks() {
    if (!filterLinks) return;
    for (var i = 0; i < filterLinks.length; i++) {
      var a = filterLinks[i];
      var href = a.getAttribute('href');
      var filter = href.replace('#', '');
      if (filter === currentFilter) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }
  }

  // --- Actions ---

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({
      id: generateId(),
      title: title,
      completed: false,
    });
    save();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    save();
    render();
  }

  function destroyTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  function editTodo(id, newTitle) {
    newTitle = newTitle.trim();
    if (!newTitle) {
      destroyTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = newTitle;
        break;
      }
    }
    editingId = null;
    save();
    render();
  }

  function startEdit(id) {
    editingId = id;
    render();
    // Focus the edit input
    var li = todoList.querySelector('[data-id="' + id + '"]');
    if (li) {
      var editInput = li.querySelector('.edit');
      if (editInput) editInput.focus();
    }
  }

  function cancelEdit() {
    editingId = null;
    render();
  }

  function toggleAllTodos() {
    var allCompleted = true;
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) { allCompleted = false; break; }
    }
    var newState = !allCompleted;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = newState;
    }
    save();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  // --- Event handlers ---

  function setupEvents() {
    // New todo input
    if (newTodoInput) {
      newTodoInput.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          addTodo(newTodoInput.value);
          newTodoInput.value = '';
        }
      });
    }

    // Todo list events (delegated)
    if (todoList) {
      todoList.addEventListener('click', function (e) {
        var target = e.target;

        // Toggle checkbox
        if (target.classList.contains('toggle')) {
          var id = findIdFromElement(target);
          if (id !== null) toggleTodo(id);
          return;
        }

        // Destroy button
        if (target.classList.contains('destroy')) {
          var id = findIdFromElement(target);
          if (id !== null) destroyTodo(id);
          return;
        }
      });

      // Double-click to edit
      todoList.addEventListener('dblclick', function (e) {
        var target = e.target;
        if (target.tagName === 'LABEL') {
          var id = findIdFromElement(target);
          if (id !== null) startEdit(id);
        }
      });

      // Edit input keydown
      todoList.addEventListener('keydown', function (e) {
        var target = e.target;
        if (!target.classList.contains('edit')) return;

        var id = findIdFromElement(target);
        if (id === null) return;

        if (e.keyCode === ENTER_KEY) {
          e.preventDefault();
          editTodo(id, target.value);
        } else if (e.keyCode === ESCAPE_KEY) {
          e.preventDefault();
          cancelEdit();
        }
      });

      // Edit input blur
      todoList.addEventListener('focusout', function (e) {
        var target = e.target;
        if (!target.classList.contains('edit')) return;

        var id = findIdFromElement(target);
        if (id === null) return;

        // Use setTimeout to avoid conflicts with click events
        setTimeout(function () {
          // Only save if still editing this todo
          if (editingId === id) {
            editTodo(id, target.value);
          }
        }, 0);
      });
    }

    // Toggle all
    if (toggleAll) {
      toggleAll.addEventListener('change', function () {
        toggleAllTodos();
      });
    }

    // Clear completed
    if (clearCompletedBtn) {
      clearCompletedBtn.addEventListener('click', function () {
        clearCompleted();
      });
    }

    // Filter links
    if (filterLinks) {
      for (var i = 0; i < filterLinks.length; i++) {
        (function (a) {
          a.addEventListener('click', function (e) {
            e.preventDefault();
            var href = a.getAttribute('href');
            currentFilter = href.replace('#', '');
            window.location.hash = href;
            render();
          });
        })(filterLinks[i]);
      }
    }

    // Hash change
    window.addEventListener('hashchange', function () {
      var hash = window.location.hash || '#/';
      var filter = hash.replace('#', '');
      if (filter === '/' || filter === '/active' || filter === '/completed') {
        currentFilter = filter;
        render();
      }
    });
  }

  function findIdFromElement(el) {
    var li = el.closest('li');
    if (!li) return null;
    return parseInt(li.dataset.id, 10);
  }

  // --- Initialize ---

  function init() {
    cacheDom();
    load();
    // Set initial filter from hash
    var hash = window.location.hash || '#/';
    var filter = hash.replace('#', '');
    if (filter === '/' || filter === '/active' || filter === '/completed') {
      currentFilter = filter;
    }
    render();
    setupEvents();
    if (newTodoInput) newTodoInput.focus();
  }

  // --- Public API (for step definitions) ---

  window.app = {
    addTodo: addTodo,
    toggleTodo: toggleTodo,
    destroyTodo: destroyTodo,
    editTodo: editTodo,
    startEdit: startEdit,
    cancelEdit: cancelEdit,
    toggleAll: toggleAllTodos,
    clearCompleted: clearCompleted,
    setFilter: function (filter) {
      currentFilter = filter;
      window.location.hash = '#' + filter;
      render();
    },
    getTodos: function () { return todos.slice(); },
    render: render,
    init: init,
  };

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

const { Given, When, Then, Before, After, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const PROJECT_ROOT = process.cwd();
const HTML_PATH = path.join(PROJECT_ROOT, 'index.html');

// --- World: per-scenario DOM and app state ---

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this._sharedStorage = {};
  }
}

setWorldConstructor(TodoWorld);

// --- Setup and teardown ---

Before(function () {
  this.window = new Window({
    url: 'http://localhost/',
    pretendToBeVisual: true,
  });
  this.document = this.window.document;

  // Use happy-dom's built-in localStorage for persistence
  // Clear it for a fresh scenario
  this.window.localStorage.clear();

  // Set globals on Node's global object so require'd app.js sees them
  global.window = this.window;
  global.document = this.document;
  global.localStorage = this.window.localStorage;
  global.location = this.window.location;
  global.DOMParser = this.window.DOMParser;

  // Load the HTML
  if (fs.existsSync(HTML_PATH)) {
    const html = fs.readFileSync(HTML_PATH, 'utf8');
    this.document.write(html);
    this.document.close();
  }

  // Load the app (fresh per scenario via cache clear)
  loadApp(this);
});

After(function () {
  if (this.window) {
    this.window.close();
  }
});

// --- Helpers ---

function app(world) {
  return world.window.app;
}

function getTodoList(world) {
  return world.document.querySelector('.todo-list');
}

function getTodos(world) {
  const list = getTodoList(world);
  if (!list) return [];
  return Array.from(list.querySelectorAll('li'));
}

function findTodoByText(world, text) {
  return getTodos(world).find(li => {
    const label = li.querySelector('label');
    return label && label.textContent.trim() === text;
  });
}

function updateCounter(world) {
  const todos = getTodos(world);
  const activeCount = todos.filter(li => !li.classList.contains('completed')).length;
  const countEl = world.document.querySelector('.todo-count');
  if (countEl) {
    countEl.innerHTML = `<strong>${activeCount}</strong> ${activeCount === 1 ? 'item' : 'items'} left`;
  }
}

function hideMainAndFooter(world) {
  const main = world.document.querySelector('.main');
  const footer = world.document.querySelector('.footer');
  if (main) main.style.display = 'none';
  if (footer) footer.style.display = 'none';
}

function loadApp(world) {
  const appPath = path.join(PROJECT_ROOT, 'js', 'app.js');
  if (!fs.existsSync(appPath)) return null;
  try {
    delete require.cache[require.resolve(appPath)];
    require(appPath);
    return true;
  } catch (e) {
    return null;
  }
}

function reloadPage(world) {
  // Capture current localStorage state before creating new window
  const oldStorage = {};
  const oldLen = world.window.localStorage.length;
  for (let i = 0; i < oldLen; i++) {
    const key = world.window.localStorage.key(i);
    oldStorage[key] = world.window.localStorage.getItem(key);
  }

  // Get current hash
  const currentHash = world.window.location.hash;

  // Create a new window to simulate reload
  const newWindow = new Window({
    url: `http://localhost/${currentHash}`,
    pretendToBeVisual: true,
  });
  const newDoc = newWindow.document;

  // Restore localStorage state to the new window
  newWindow.localStorage.clear();
  for (const key of Object.keys(oldStorage)) {
    newWindow.localStorage.setItem(key, oldStorage[key]);
  }

  // Set globals on Node's global object
  global.window = newWindow;
  global.document = newDoc;
  global.localStorage = newWindow.localStorage;
  global.location = newWindow.location;
  global.DOMParser = newWindow.DOMParser;

  // Load the HTML
  if (fs.existsSync(HTML_PATH)) {
    const html = fs.readFileSync(HTML_PATH, 'utf8');
    newDoc.write(html);
    newDoc.close();
  }

  // Close old window and switch to new
  world.window.close();
  world.window = newWindow;
  world.document = newDoc;

  // Load the app
  loadApp(world);
}

// --- Given steps ---

Given('the todo application is loaded', function () {
  hideMainAndFooter(this);
});

Given('the todo application is loaded with no todos', function () {
  hideMainAndFooter(this);
});

Given('the todo application with todos {string}', function (text) {
  const a = app(this);
  if (a) {
    a.addTodo(text);
  } else {
    // Fallback: direct DOM manipulation
    const list = getTodoList(this);
    if (list) {
      const id = Date.now() + Math.floor(Math.random() * 1000);
      const li = this.document.createElement('li');
      li.dataset.id = id;
      li.innerHTML = `<div class="view"><input class="toggle" type="checkbox"><label>${text}</label><button class="destroy"></button></div><input class="edit" value="${text}">`;
      list.appendChild(li);
      updateCounter(this);
    }
  }
});

Given('the todo application with todos {string} and {string}', function (text1, text2) {
  const a = app(this);
  if (a) {
    a.addTodo(text1);
    a.addTodo(text2);
  } else {
    const list = getTodoList(this);
    if (list) {
      [text1, text2].forEach(text => {
        const id = Date.now() + Math.floor(Math.random() * 1000);
        const li = this.document.createElement('li');
        li.dataset.id = id;
        li.innerHTML = `<div class="view"><input class="toggle" type="checkbox"><label>${text}</label><button class="destroy"></button></div><input class="edit" value="${text}">`;
        list.appendChild(li);
      });
      updateCounter(this);
    }
  }
});

Given('the todo application with completed todos {string}', function (text) {
  const a = app(this);
  if (a) {
    a.addTodo(text);
    // Find the todo and toggle it
    const todos = a.getTodos();
    if (todos.length > 0) {
      a.toggleTodo(todos[todos.length - 1].id);
    }
  } else {
    const list = getTodoList(this);
    if (list) {
      const id = Date.now() + Math.floor(Math.random() * 1000);
      const li = this.document.createElement('li');
      li.dataset.id = id;
      li.classList.add('completed');
      li.innerHTML = `<div class="view"><input class="toggle" type="checkbox" checked><label>${text}</label><button class="destroy"></button></div><input class="edit" value="${text}">`;
      list.appendChild(li);
      updateCounter(this);
    }
  }
});

Given('the todo application with completed todos {string} and active todos {string}', function (completedText, activeText) {
  const a = app(this);
  if (a) {
    a.addTodo(completedText);
    a.addTodo(activeText);
    // Toggle the first one to completed
    const todos = a.getTodos();
    if (todos.length > 0) {
      a.toggleTodo(todos[0].id);
    }
  } else {
    const list = getTodoList(this);
    if (list) {
      // Add completed todo
      const id1 = Date.now() + Math.floor(Math.random() * 1000);
      const li1 = this.document.createElement('li');
      li1.dataset.id = id1;
      li1.classList.add('completed');
      li1.innerHTML = `<div class="view"><input class="toggle" type="checkbox" checked"><label>${completedText}</label><button class="destroy"></button></div><input class="edit" value="${completedText}">`;
      list.appendChild(li1);
      // Add active todo
      const id2 = Date.now() + Math.floor(Math.random() * 1000) + 1;
      const li2 = this.document.createElement('li');
      li2.dataset.id = id2;
      li2.innerHTML = `<div class="view"><input class="toggle" type="checkbox"><label>${activeText}</label><button class="destroy"></button></div><input class="edit" value="${activeText}">`;
      list.appendChild(li2);
      updateCounter(this);
    }
  }
});

Given('the todo application with completed todos {string} and {string}', function (text1, text2) {
  const a = app(this);
  if (a) {
    a.addTodo(text1);
    a.addTodo(text2);
    // Toggle both to completed
    const todos = a.getTodos();
    todos.forEach(t => a.toggleTodo(t.id));
  } else {
    const list = getTodoList(this);
    if (list) {
      [text1, text2].forEach(text => {
        const id = Date.now() + Math.floor(Math.random() * 1000);
        const li = this.document.createElement('li');
        li.dataset.id = id;
        li.classList.add('completed');
        li.innerHTML = `<div class="view"><input class="toggle" type="checkbox" checked"><label>${text}</label><button class="destroy"></button></div><input class="edit" value="${text}">`;
        list.appendChild(li);
      });
      updateCounter(this);
    }
  }
});

// --- When steps ---

When('the user types {string} in the new todo input and presses Enter', function (text) {
  const a = app(this);
  if (a) {
    a.addTodo(text);
  } else {
    throw new Error('App not loaded');
  }
});

When('the user clicks the toggle-all checkbox', function () {
  const a = app(this);
  if (a) {
    a.toggleAll();
  } else {
    throw new Error('App not loaded');
  }
});

When('the user marks the todo {string} as completed', function (text) {
  const a = app(this);
  if (a) {
    const todos = a.getTodos();
    const todo = todos.find(t => t.title === text && !t.completed);
    if (todo) a.toggleTodo(todo.id);
  } else {
    throw new Error('App not loaded');
  }
});

When('the user marks the todo {string} as active', function (text) {
  const a = app(this);
  if (a) {
    const todos = a.getTodos();
    const todo = todos.find(t => t.title === text && t.completed);
    if (todo) a.toggleTodo(todo.id);
  } else {
    throw new Error('App not loaded');
  }
});

When('the user hovers over the todo {string}', function (text) {
  const li = findTodoByText(this, text);
  if (li) {
    li.classList.add('hover');
    li.dispatchEvent(new this.window.Event('mouseenter', { bubbles: true }));
  }
});

When('the user clicks the destroy button for todo {string}', function (text) {
  const a = app(this);
  if (a) {
    const todos = a.getTodos();
    const todo = todos.find(t => t.title === text);
    if (todo) a.destroyTodo(todo.id);
  } else {
    throw new Error('App not loaded');
  }
});

When('the user clicks the checkbox for todo {string}', function (text) {
  const a = app(this);
  if (a) {
    const todos = a.getTodos();
    const todo = todos.find(t => t.title === text);
    if (todo) a.toggleTodo(todo.id);
  } else {
    throw new Error('App not loaded');
  }
});

When('the user double-clicks the label for todo {string}', function (text) {
  const a = app(this);
  if (a) {
    const todos = a.getTodos();
    const todo = todos.find(t => t.title === text);
    if (todo) a.startEdit(todo.id);
  } else {
    throw new Error('App not loaded');
  }
});

When('the user types {string} in the edit input', function (text) {
  const editing = this.document.querySelector('.editing');
  if (!editing) throw new Error('No editing todo found');
  const editInput = editing.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  editInput.value = text;
});

When('the user presses Enter', function () {
  const a = app(this);
  if (!a) throw new Error('App not loaded');
  const editing = this.document.querySelector('.editing');
  if (!editing) throw new Error('No editing todo found');
  const editInput = editing.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  const id = parseInt(editing.dataset.id, 10);
  a.editTodo(id, editInput.value);
});

When('the user presses Escape', function () {
  const a = app(this);
  if (!a) throw new Error('App not loaded');
  a.cancelEdit();
});

When('the user blurs the edit input', function () {
  const a = app(this);
  if (!a) throw new Error('App not loaded');
  const editing = this.document.querySelector('.editing');
  if (!editing) throw new Error('No editing todo found');
  const editInput = editing.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  const id = parseInt(editing.dataset.id, 10);
  a.editTodo(id, editInput.value);
});

When('the user clears the edit input', function () {
  const editing = this.document.querySelector('.editing');
  if (!editing) throw new Error('No editing todo found');
  const editInput = editing.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  editInput.value = '';
});

When('the user clicks the clear completed button', function () {
  const a = app(this);
  if (a) {
    a.clearCompleted();
  } else {
    throw new Error('App not loaded');
  }
});

When('the user navigates to {string}', function (hash) {
  const a = app(this);
  if (a) {
    const filter = hash.replace('#', '');
    a.setFilter(filter);
  } else {
    throw new Error('App not loaded');
  }
});

When('the user reloads the page', function () {
  reloadPage(this);
});

When('the user creates and deletes a todo {string}', function (text) {
  const a = app(this);
  if (a) {
    a.addTodo(text);
    const todos = a.getTodos();
    const todo = todos.find(t => t.title === text);
    if (todo) a.destroyTodo(todo.id);
  } else {
    throw new Error('App not loaded');
  }
});

When('the user creates todos {string} and {string}', function (text1, text2) {
  const a = app(this);
  if (a) {
    a.addTodo(text1);
    a.addTodo(text2);
  } else {
    throw new Error('App not loaded');
  }
});

// --- Then steps ---

Then('the main section is not visible', function () {
  const main = this.document.querySelector('.main');
  const isHidden = !main || main.style.display === 'none';
  if (!isHidden) throw new Error('Main section is visible but should be hidden');
});

Then('the footer is not visible', function () {
